class LocalSearchEngine:
    def __init__(self, chunk_size=5):
        self.chunk_size = chunk_size
        self.index = []  # list of {"source": str, "chunk": int, "text": str, "vectors": list}

    def _token_vec(self, token: str) -> list[float]:
        vec = [0.0] * 26
        for c in token.lower():
            if 'a' <= c <= 'z':
                vec[ord(c) - ord('a')] += 1.0
        return vec

    def _encode(self, text: str) -> list[list[float]]:
        return [self._token_vec(w) for w in text.lower().split() if w.strip()]

    def _dot(self, a: list[float], b: list[float]) -> float:
        return sum(x * y for x, y in zip(a, b))

    def _maxsim(self, q_vecs: list[list[float]], d_vecs: list[list[float]]) -> float:
        if not q_vecs or not d_vecs:
            return 0.0
        total = 0.0
        for qv in q_vecs:
            total += max(self._dot(qv, dv) for dv in d_vecs)
        return total

    def _chunk_text(self, text: str) -> list[str]:
        words = text.split()
        n = max(1, int(self.chunk_size))
        return [" ".join(words[i:i + n]) for i in range(0, len(words), n)]

    def ingest(self, documents: list[dict]):
        for doc in documents:
            source = doc.get("source", "")
            for i, chunk in enumerate(self._chunk_text(doc.get("text", ""))):
                self.index.append({
                    "source": source,
                    "chunk": i,
                    "text": chunk,
                    "vectors": self._encode(chunk),
                })

    def search(self, query: str, k: int = 3) -> list[dict]:
        q_vecs = self._encode(query)
        scored = []
        for entry in self.index:
            score = self._maxsim(q_vecs, entry["vectors"])
            scored.append({"source": entry["source"], "text": entry["text"], "score": score})
        scored.sort(key=lambda r: r["score"], reverse=True)
        return scored[:k]

    def save_index(self) -> list[dict]:
        return [dict(e, vectors=[list(v) for v in e["vectors"]]) for e in self.index]

    def load_index(self, data: list[dict]):
        self.index = [dict(e, vectors=[list(v) for v in e["vectors"]]) for e in data]


