engine = LocalSearchEngine(chunk_size=4)
engine.ingest([
    {"source": "notes.txt", "text": "gradient descent optimizes neural network weights by updating parameters"},
    {"source": "guide.md", "text": "decision trees split data by feature thresholds for classification"},
])

results = engine.search("gradient optimization", k=2)
print(results[0]["source"])
print(results[0]["score"] > results[1]["score"])

saved = engine.save_index()
engine2 = LocalSearchEngine(chunk_size=4)
engine2.load_index(saved)
results2 = engine2.search("gradient optimization", k=1)
print(results2[0]["source"])
print(len(saved) > 0)

class FileSearchCLI:
    def __init__(self):
        self.chunk_size = 6
        self.index = []  # {"path": str, "filetype": str, "chunk": int, "text": str, "vectors": list}

    def _token_vec(self, token: str) -> list[float]:
        vec = [0.0] * 26
        for c in token.lower():
            if 'a' <= c <= 'z':
                vec[ord(c) - ord('a')] += 1.0
        return vec

    def _encode(self, text: str) -> list[list[float]]:
        return [self._token_vec(w) for w in text.lower().split() if w.strip()]

    def _dot(self, a: list[float], b: list[float]) -> float:
        return sum(x * y for x, y in zip(a, b))

    def _maxsim(self, q_vecs, d_vecs) -> float:
        if not q_vecs or not d_vecs:
            return 0.0
        return sum(max(self._dot(qv, dv) for dv in d_vecs) for qv in q_vecs)

    def _chunk(self, text: str) -> list[str]:
        words = text.split()
        if not words:
            return []
        return [" ".join(words[i:i+self.chunk_size])
                for i in range(0, len(words), self.chunk_size)]

    def add_files(self, file_entries: list[dict]):
        for entry in file_entries:
            for i, text in enumerate(self._chunk(entry["content"])):
                self.index.append({
                    "path": entry["path"],
                    "filetype": entry["filetype"],
                    "chunk": i,
                    "text": text,
                    "vectors": self._encode(text),
                })

    def search(self, query: str, k: int = 3, filetype: str = None) -> list[dict]:
        q_vecs = self._encode(query)
        results = []
        for item in self.index:
            if filetype is not None and item["filetype"] != filetype:
                continue
            results.append({
                "path": item["path"],
                "filetype": item["filetype"],
                "text": item["text"],
                "score": self._maxsim(q_vecs, item["vectors"]),
            })
        results.sort(key=lambda r: r["score"], reverse=True)
        return results[:k]

    def stats(self) -> dict:
        paths = set()
        type_paths = {}
        for item in self.index:
            paths.add(item["path"])
            type_paths.setdefault(item["filetype"], set()).add(item["path"])
        return {
            "total_chunks": len(self.index),
            "total_files": len(paths),
            "filetypes": {ft: len(p) for ft, p in type_paths.items()},
        }


cli = FileSearchCLI()
cli.add_files([
    {"path": "app.py", "content": "async function handles web requests with error handling", "filetype": "py"},
    {"path": "readme.md", "content": "installation guide for setting up the project dependencies", "filetype": "md"},
    {"path": "utils.py", "content": "helper functions for data parsing and validation logic", "filetype": "py"},
])

r_all = cli.search("error handling", k=2)
